def build(k,platform,carousel=False):
    c=C[k]
    if platform=='tiktok': return c['tt']+' Follow for the next drop 💎\n'+c['tt_tags']
    if platform=='instagram':
        h,ls=(c['car_hook'],c['car_lines']) if carousel else (c['hook'],c['lines'])
        return h+'\n'+'\n'.join(ls)+'\nDM us to order 💌\n'+c['ig_tags']
    if platform=='threads': return c['th']+' DM us on IG'
    if platform=='twitter': return c['x']
    if platform=='pinterest': return c['pin']+'\n'+c['pin_tags']
    if platform=='youtube': return c['yt']+'\nSee it: '+L+'#'+k+' · Subscribe for daily crystals '+c['yt_tags']
